from datetime import UTC, datetime, timedelta

from accounts.reset_tokens import (
    TOKEN_TTL,
    ResetRecord,
    issue_reset_token,
    verify_reset_token,
)


class MemoryStore:
    def __init__(self) -> None:
        self.records: dict[str, ResetRecord] = {}

    def save(self, record: ResetRecord) -> None:
        self.records[record.account_id] = record

    def take(self, account_id: str) -> ResetRecord | None:
        return self.records.pop(account_id, None)


NOW = datetime(2026, 1, 1, tzinfo=UTC)


def test_valid_token_verifies_once() -> None:
    store = MemoryStore()
    token = issue_reset_token(store, "a1", NOW)
    assert verify_reset_token(store, "a1", token, NOW)
    assert not verify_reset_token(store, "a1", token, NOW)


def test_token_is_not_stored_in_plaintext() -> None:
    store = MemoryStore()
    token = issue_reset_token(store, "a1", NOW)
    assert token not in store.records["a1"].token_digest


def test_wrong_token_fails_and_consumes_record() -> None:
    store = MemoryStore()
    token = issue_reset_token(store, "a1", NOW)
    assert not verify_reset_token(store, "a1", "wrong", NOW)
    assert not verify_reset_token(store, "a1", token, NOW)


def test_expired_token_fails() -> None:
    store = MemoryStore()
    token = issue_reset_token(store, "a1", NOW)
    assert not verify_reset_token(store, "a1", token, NOW + TOKEN_TTL + timedelta(seconds=1))


def test_token_for_other_account_fails() -> None:
    store = MemoryStore()
    token = issue_reset_token(store, "a1", NOW)
    assert not verify_reset_token(store, "a2", token, NOW)

